const wrapLink=u=>mutateSelectedRuns('پیوند',{href:u});const setHeader=v=>{transaction('سربرگ',model=>{state.pageSettings.header=v;model.settings={...model.settings,header:v};model.sections[0].header={blocks:v?[{id:'header-1',type:'paragraph',runs:[{text:v}]}]:[]}})};
